function sortKeys(o) {
    if (Array.isArray(o)) return o.map(sortKeys);
    if (o && typeof o === 'object') {
        const out = {};
        for (const k of Object.keys(o).sort()) out[k] = sortKeys(o[k]);
        return out;
    }
    return o;
}
const norm = o => JSON.stringify(sortKeys(o));
